SELECT i.name, i.is_unique, i.filter_definition, (SELECT STRING_AGG(c.name + ':' + CAST(ic.is_included_column AS varchar) + ':' + CAST(ic.is_descending_key AS varchar), ',') WITHIN GROUP (ORDER BY ic.key_ordinal, c.name) FROM sys.index_columns ic JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id) cols FROM sys.indexes i WHERE i.object_id = OBJECT_ID('dbo.T') ORDER BY i.name
